def compute(vars):
    benefits_payments = vars["v1"]
    deferred_compensation = vars["v2"]

    if deferred_compensation == 0:
        return None

    value = benefits_payments / deferred_compensation

    return {
        "value": value,
        "trace": {
            "benefits_payments": benefits_payments,
            "deferred_compensation": deferred_compensation,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
